import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import datetime

# Configuration
sns.set_theme(style="whitegrid", palette="muted")
plt.rcParams.update({'font.size': 12})

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')

# Convert timestamps
print("Converting timestamps...")
df['recorded_at'] = pd.to_datetime(df['recorded_at'])
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'])

# Calculate lag in hours
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600.0

# 1. Dataset Overview
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = df['fuel_type'].unique().tolist()
min_date = df['recorded_at'].min().strftime('%Y-%m-%d')
max_date = df['recorded_at'].max().strftime('%Y-%m-%d')

# 2. Price Distribution by Fuel Type
print("Calculating price distributions...")
price_stats = df.groupby('fuel_type')['price_pence'].agg(['mean', 'median', 'min', 'max', 'std', 'count']).reset_index()
# Calculate IQR manually or using quantile
q1 = df.groupby('fuel_type')['price_pence'].quantile(0.25).reset_index(name='Q1')
q3 = df.groupby('fuel_type')['price_pence'].quantile(0.75).reset_index(name='Q3')
price_stats = price_stats.merge(q1, on='fuel_type').merge(q3, on='fuel_type')
price_stats['IQR'] = price_stats['Q3'] - price_stats['Q1']
price_stats['spread'] = price_stats['max'] - price_stats['min']

# Visualisation 1: Box plot of prices by fuel type
fig1, ax1 = plt.subplots(figsize=(10, 6))
sns.boxplot(x='price_pence', y='fuel_type', data=df, ax=ax1, order=price_stats.sort_values('median', ascending=False)['fuel_type'])
ax1.set_title('Price Distribution by Fuel Type (Pence per Litre)')
ax1.set_xlabel('Price (Pence)')
ax1.set_ylabel('Fuel Type')
img_price_dist = fig_to_base64(fig1)

# 3. Update Freshness
print("Calculating update freshness...")
freshness_stats = df.groupby('fuel_type')['update_lag_hours'].median().reset_index(name='median_lag_hours')
overall_median_lag = df['update_lag_hours'].median()

# Visualisation 2: Histogram of update lag
fig2, ax2 = plt.subplots(figsize=(10, 6))
sns.histplot(df[df['update_lag_hours'] < 168]['update_lag_hours'], bins=50, ax=ax2, kde=True) # Cap at 1 week (168h) for better visualization
ax2.set_title('Distribution of Retailer Reporting Lag (up to 1 week)')
ax2.set_xlabel('Lag (Hours between source update and record)')
ax2.set_ylabel('Frequency')
img_lag_dist = fig_to_base64(fig2)

# 4. Station Coverage
print("Calculating station coverage...")
station_fuel_counts = df.groupby('node_id')['fuel_type'].nunique().reset_index(name='fuel_type_count')
station_coverage_stats = station_fuel_counts['fuel_type_count'].value_counts().sort_index().reset_index()
station_coverage_stats.columns = ['fuel_type_count', 'number_of_stations']

# Count stations per fuel type
stations_per_fuel = df.groupby('fuel_type')['node_id'].nunique().reset_index(name='station_count')
stations_per_fuel['coverage_percent'] = (stations_per_fuel['station_count'] / unique_stations) * 100

# Visualisation 3: Bar chart of stations per fuel type
fig3, ax3 = plt.subplots(figsize=(8, 5))
sns.barplot(x='station_count', y='fuel_type', data=stations_per_fuel.sort_values('station_count', ascending=False), ax=ax3)
ax3.set_title('Number of Stations Reporting Each Fuel Type')
ax3.set_xlabel('Number of Stations')
ax3.set_ylabel('Fuel Type')
img_coverage = fig_to_base64(fig3)

# Generate HTML
print("Generating HTML...")
html_template = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>UK Retail Fuel Price Trend Analysis — February 2026</title>
    <style>
        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: #333;
            max-width: 1200px;
            margin: 0 auto;
