            padding: 12px 15px;
            text-align: right;
            border-bottom: 1px solid #e0e0e0;
        }}
        th {{
            background-color: #f2f6f8;
            color: #2c3e50;
            font-weight: 600;
        }}
        td:first-child, th:first-child {{
            text-align: left;
        }}
        tr:hover {{
            background-color: #f5f5f5;
        }}
        .chart-container {{
            background-color: #fff;
            padding: 20px;
